  const code = text => `<pre class="code-box">${esc(text)}</pre>`;
  function task(number, page, cat, q, answer, hint, explain, distractors) {
    const item = { id: `ark_${stage}_${number}`, stage, cat, pts: 1, q, hint, explain,
      source: { file: stages[stage].file, number: String(number).replace(/_/g, '.'), page } };
    if (distractors) {
      // Stała kolejność odpowiedzi także po odświeżeniu, różne pozycje rozwiązania.
      const position = [...item.id].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7) % (distractors.length + 1);
      item.options = [...distractors];
      item.options.splice(position, 0, answer);
      item.correct = position;
    } else {
      item.accepted = (Array.isArray(answer) ? answer : [answer]).map(String);
      item.placeholder = 'Wpisz odpowiedź…';
    }
    tasks.push(item);
  }

