  task('9',4,'app','W Koszu Windows wybierasz Przywróć. Dokąd zwykle trafi plik?', 'Do folderu, z którego został usunięty', 'Przywrócenie odtwarza wcześniejsze położenie.', 'Polecenie Przywróć przywraca plik do pierwotnej lokalizacji, o ile jest dostępna.', ['Zawsze na Pulpit','Zawsze do folderu Muzyka','Wyłącznie do chmury']);
  task('10',5,'app','Jak po polsku zwykle nazywa się format krótkiego filmu „reel” w mediach społecznościowych?', ['rolka'], 'Nazwa kojarzy się z nawiniętą taśmą filmową.', 'To <strong>rolka</strong>. Długość filmów i funkcje aplikacji mogą się zmieniać, dlatego tu ćwiczymy nazwę formatu.');
  task('13',5,'hw','Co może przesyłać połączenie HDMI między komputerem a monitorem z głośnikami?', 'Obraz i dźwięk', 'To cyfrowe połączenie multimedialne.', 'HDMI może przenosić zarówno obraz, jak i dźwięk, gdy obsługują je połączone urządzenia.', ['Wyłącznie obraz','Wyłącznie dźwięk','Wyłącznie ruch myszy']);

  // ETAP REJONOWY – GRUDZIEŃ 2024
  stage = 'rejonowy24xii';
  task('1',2,'app','Czy hiperłącza z prezentacji mogą pozostać klikalne po poprawnym eksporcie do PDF-u?', 'Tak', 'Statyczny wygląd strony nie oznacza, że dokument nie może zawierać linków.', 'PDF może zachować hiperłącza. Nie należy mylić odsyłaczy z animacjami i przejściami slajdów.', ['Nie']);
  task('3',2,'app','Na dole każdej strony mają się powtarzać numer strony i kod ucznia. Gdzie je umieścisz?', 'W stopce', 'Przypis objaśnia fragment tekstu, a tu chodzi o powtarzalny element strony.', '<strong>Stopka</strong> znajduje się u dołu strony. Numer strony można wstawić jako automatyczne pole.', ['W przypisie dolnym','W indeksie górnym','Wyłącznie w tytule dokumentu']);
  task('5',3,'excel','Chcesz uporządkować szkoły: najpierw powiatami, w każdym powiecie gminami, a w każdej gminie nazwami. Jaka kolejność kluczy sortowania będzie poprawna?', 'Powiat → Gmina → Nazwa szkoły', 'Zacznij od największej grupy, a potem przejdź do mniejszych.', 'Najpierw grupujemy według powiatu. Drugi klucz porządkuje gminy wewnątrz powiatu, trzeci nazwy szkół wewnątrz gminy.', ['Nazwa szkoły → Gmina → Powiat','Gmina → Nazwa szkoły → Powiat','Nazwa szkoły → Powiat → Gmina']);
  task('6_a',4,'excel','Nagłówek „Liczba głosów” ma mieścić się w dwóch wierszach tej samej komórki. Która opcja pomoże?', 'Zawijaj tekst', 'Nie musisz tworzyć drugiej komórki.', '<strong>Zawijaj tekst</strong> rozkłada zawartość na wiersze wewnątrz komórki. Wysokość wiersza musi wystarczyć do jej pokazania.', ['Usuń wiersz','Sortuj malejąco','Ukryj kolumnę']);
  task('6_b',4,'excel','Wykres udziałów wygląda jak koło z otworem pośrodku. Jak się nazywa?', 'Pierścieniowy', 'Kształt przypomina pierścień.', '<strong>Wykres pierścieniowy</strong> przedstawia udziały części w całości. Otwór w środku odróżnia go od zwykłego kołowego.', ['Punktowy','Radarowy','Liniowy']);
  task('6_c',4,'excel','W wyborach oddano 26 głosów, a Jasiu dostał 8. Na wykresie widnieje przy nim 31%. Co przedstawia etykieta?', 'Udział procentowy głosów Jasia w całości', 'Porównaj liczbę głosów kandydata z łączną liczbą głosów.', '8 ÷ 26 × 100% ≈ 30,77%, po zaokrągleniu <strong>31%</strong>. To nie liczba głosów, tylko udział.', ['Dokładną liczbę głosów','Numer kandydata','Liczbę nieobecnych']);
  task('7',4,'app','Które pole e-maila pozwala ukryć adresy odbiorców przed innymi adresatami?', ['UDW','BCC'], 'Skrót po polsku oznacza „Ukryte do wiadomości”.', '<strong>UDW (BCC)</strong> ukrywa listę tych odbiorców przed pozostałymi adresatami. Pole DW tego nie robi.');
  task('8_a',5,'bin','Ile jedynek jest w binarnym zapisie wyniku 10²?', '3', 'Najpierw oblicz potęgę w systemie dziesiętnym.', '10² = 100. 100 = 64 + 32 + 4 = 1100100₂, więc są <strong>3 jedynki</strong>.');
  task('8_b',5,'bin','Ile jedynek ma binarny zapis wyniku <code>987 div 65</code>?', '4', '65 × 15 = 975. Reszty nie zamieniaj na część ułamkową.', '987 div 65 = 15. 15 = 1111₂, więc są <strong>4 jedynki</strong>.');
  task('8_c',5,'bin','Ile jedynek ma binarny zapis wyniku <code>432 mod 10</code>?', '1', 'Reszta z dzielenia dodatniej liczby przez 10 to jej ostatnia cyfra.', '432 mod 10 = 2. 2 = 10₂, więc jest <strong>1 jedynka</strong>.');
  task('9_a',5,'hw','Wstaw właściwy znak: <code>200 Mb/s ? 100 MB/s</code>.', '&lt;', '1 bajt to 8 bitów. Wielkość litery B ma znaczenie.', '100 MB/s = 800 Mb/s, dlatego <strong>200 Mb/s &lt; 100 MB/s</strong>.', ['=','&gt;']);
  task('9_b',5,'hw','Wstaw właściwy znak: <code>3 GHz ? 3000 MHz</code>.', '=', 'Przedrostki giga i mega różnią się tu tysiąckrotnie.', '1 GHz = 1000 MHz, więc <strong>3 GHz = 3000 MHz</strong>.', ['&lt;','&gt;']);
  task('9_c',5,'hw','Wstaw właściwy znak: <code>20 cm ? 10 cali</code>. Przyjmij 1 cal = 2,54 cm.', '&lt;', 'Zamień cale na centymetry przed porównaniem.', '10 × 2,54 cm = 25,4 cm. <strong>20 cm &lt; 25,4 cm</strong>.', ['=','&gt;']);
  task('10_a',5,'bin','Masz 100 nieskompresowanych zdjęć 3000 × 4000 pikseli. Każdy piksel zajmuje 3 bajty. Pomijamy nagłówki. Ile GB zajmują wszystkie? Przyjmij 1 GB = 1 000 000 000 B.', ['3,6','3.6','3,6 GB','3.6 GB'], 'Policz piksele jednego zdjęcia, potem bajty, a na końcu 100 zdjęć.', '3000 × 4000 × 3 × 100 = 3 600 000 000 B, czyli <strong>3,6 GB</strong>.');
  task('10_b',5,'bin','Nagranie zajmuje 32 kB na sekundę. Ile MB zajmie 10 minut? Przyjmij 1000 kB = 1 MB.', ['19,2','19.2','19,2 MB','19.2 MB'], '10 minut to 600 sekund. Najpierw pomnóż, potem zamień jednostki.', '600 × 32 kB = 19 200 kB = <strong>19,2 MB</strong>.');
  task('11_a',6,'algo','Duszek Scratch z opuszczonym pisakiem powtarza 5 razy: przesuń o 100 kroków, obróć o 72°. Co rysuje?', 'Pięciokąt foremny', 'Pięć równych odcinków, a suma obrotów wynosi 360°.', '5 × 72° = 360°. Równe odcinki i równe skręty tworzą <strong>pięciokąt foremny</strong>.', ['Kwadrat','Trójkąt','Gwiazdę pięcioramienną']);
  task('11_b',6,'algo','Duszek powtarza 5 razy: przesuń o 100 kroków, obróć o 144°. Pisak jest opuszczony. Co powstaje?', 'Gwiazda pięcioramienna', 'Większy skręt powoduje przecinanie wcześniejszych odcinków.', 'Obrót 144° po każdym z pięciu równych odcinków daje <strong>gwiazdę pięcioramienną</strong>.', ['Pięciokąt foremny','Koło','Kwadrat']);
  task('11_c',6,'algo','Duszek powtarza 5 razy: idź 100, idź −100, obróć 72°. Pisak jest opuszczony. Co się dzieje?', 'Rysuje pięć odcinków wychodzących ze wspólnego punktu', 'Po drugim ruchu duszek jest z powrotem tam, gdzie zaczął dany odcinek.', 'Ruchy 100 i −100 wzajemnie się cofają. Po każdym powrocie następuje obrót, więc powstaje pięć promieni.', ['Rysuje okrąg','Wcale się nie porusza','Rysuje pięciokąt bez wracania do środka']);
  task('12',6,'excel','Kolumny Excela oznaczamy literami A=1, …, Z=26. Numer XFD oblicz jako <code>24×26² + 6×26 + 4</code>. Która to kolumna?', '16384', '26² = 676. Uważaj, aby nie pomylić kolumny z numerem wiersza.', '24 × 676 + 6 × 26 + 4 = 16 224 + 156 + 4 = <strong>16 384</strong>.');
  task('13_a',7,'algo','Program ma dodawać 1/1 + 1/2 + … + 1/N. Co wpiszesz w miejsce znaku zapytania?'+code('suma = 0\nfor i in range(1, ?):\n    suma = suma + 1 / i'), ['N+1','N + 1','1+N','1 + N'], 'Druga granica range nie wchodzi do pętli.', 'Aby ostatnią wartością i było N, wpisz <code>N + 1</code>. Przykład: range(1, 5) daje 1, 2, 3, 4.');
  task('13_b',7,'algo','Dlaczego w Pythonie do sumowania 1/1 + 1/2 + … używamy <code>1 / i</code>, a nie <code>1 // i</code>?', 'Operator / zachowuje wynik ułamkowy', 'Sprawdź różnicę pomiędzy 1/2 i 1//2.', '<code>1 / 2 = 0.5</code>, natomiast <code>1 // 2 = 0</code>. W tej sumie potrzebujemy ułamków.', ['Operator // zawsze dodaje liczby','Operator / porównuje teksty','Oba zapisy zawsze dają to samo']);
  task('14_a',7,'algo','Algorytm Euklidesa: od większej liczby odejmuj mniejszą aż będą równe. Jaki NWD otrzymasz dla 24 i 40?', '8', 'Zapisuj kolejne pary, nie zmieniając obu liczb jednocześnie.', '(24,40) → (24,16) → (8,16) → (8,8). Wynik: <strong>NWD = 8</strong>.');
  task('14_b',7,'algo','Ile odejmowań wykona algorytm Euklidesa dla x=16 i y=16, jeśli kończy od razu po stwierdzeniu równości?', '0', 'Warunek zakończenia jest spełniony już na początku.', 'Liczby od razu są równe. NWD wynosi 16, a liczba odejmowań to <strong>0</strong>.');
  task('15',8,'app','Komórka tabeli HTML ma obejmować trzy kolumny. Jaki atrybut wpiszesz w znaczniku td?', '<code>colspan="3"</code>', '„Column” oznacza kolumnę, a „span” — rozpiętość.', '<code>&lt;td colspan="3"&gt;</code> obejmuje trzy kolumny. <code>rowspan</code> dotyczy wierszy.', ['<code>rowspan="3"</code>','<code>width="3"</code>','<code>title="3"</code>']);
  task('17',9,'bin','Czy binarny zapis dodatniej liczby, bez zer wiodących, może być krótszy od jej zapisu szesnastkowego?', 'Nie', 'Jedna cyfra HEX może zastąpić nawet cztery cyfry binarne.', 'System szesnastkowy zapisuje więcej wartości jedną cyfrą. Zapis BIN może mieć tę samą długość (np. 1) albo być dłuższy.', ['Tak']);
  task('18',9,'logic','Cztery drużyny grają każdy z każdym po jednym meczu. Za wygraną są 3 pkt, remis 1, porażkę 0. A wygrywa wszystkie mecze; B pokonuje C i D; C remisuje z D. Ile punktów ma C?', '1', 'C przegrywa z A i B. Zostaje mecz z D.', 'Dwie porażki dają 0 punktów, a remis z D daje 1. Drużyna C zdobywa <strong>1 punkt</strong>.');

