  task('2',2,'hw','Telefon udostępnia internet innym urządzeniom przez swoją sieć Wi-Fi. Jak nazywa się ta funkcja?', 'Hotspot / punkt dostępu', 'Telefon pełni tu rolę punktu, do którego łączą się inne urządzenia.', '<strong>Hotspot</strong> pozwala udostępnić połączenie, np. z sieci komórkowej, innym urządzeniom przez Wi-Fi.', ['Tryb samolotowy','Kosz','Przypis dolny']);
  task('3_a',3,'bin','Wstaw 0 lub 1 tak, aby <code>1?111₂ &lt; 25₁₀</code>.', '0', 'Porównaj dwie możliwe liczby: 10111₂ i 11111₂.', '10111₂ = 23, a 11111₂ = 31. Tylko <strong>0</strong> daje liczbę mniejszą od 25.');
  task('3_b',3,'bin','Wstaw <strong>najmniejszą</strong> cyfrę HEX w miejsce ?, tak aby <code>25₁₀ &lt; 1?₁₆</code>.', 'A', 'Liczba 19₁₆ jest równa 25. Potrzebujesz większej.', '1A₁₆ = 16 + 10 = 26. <strong>A</strong> jest najmniejszą pasującą cyfrą. W oryginale, bez wymogu najmniejszej, pasują także B–F.');
