  task('2',2,'bin','Data etapu szkolnego to 13 listopada. Jak zapisać dzień i miesiąc binarnie, w kolejności dzień–miesiąc?', '1101–1011', '13 = 8+4+1. Listopad to miesiąc 11.', '13₁₀ = 1101₂, a 11₁₀ = 1011₂. Poprawna para to <strong>1101–1011</strong>.', ['1011–1101','1111–1010','1100–1001']);
  task('4',2,'hw','Jak nazywa się publikowanie przez rodziców informacji i zdjęć dotyczących ich dzieci w internecie?', 'Sharenting', 'Słowo łączy sharing (dzielenie się) i parenting (rodzicielstwo).', '<strong>Sharenting</strong> oznacza udostępnianie przez rodziców treści dotyczących dzieci. Warto chronić ich prywatność i brać pod uwagę ich zdanie.', ['Phishing','Defragmentacja','Routing']);
  task('5',2,'app','Dopasuj skróty w Wordzie: Ctrl+B, Ctrl+I, Ctrl+U.', 'Pogrubienie, kursywa, podkreślenie', 'Litery pochodzą od bold, italic i underline.', '<kbd>Ctrl+B</kbd> — pogrubienie; <kbd>Ctrl+I</kbd> — kursywa; <kbd>Ctrl+U</kbd> — podkreślenie.', ['Podkreślenie, pogrubienie, kursywa','Kopiowanie, wklejanie, wycinanie','Zapis, druk, zamknięcie']);
